    def all_project_ai_endpoints(
        self, service_name: str
    ) -> t.Iterator[models.CloudProjectAiEndpointsModel]:
        """all_project_ai_endpoints iterates over GET /v1/cloud/project/{serviceName}/ai/endpoint (List AI Endpoints models available to the project).

        It lists the IDs with list_project_ai_endpoints, then gets each object with get_project_ai_endpoint,
        only when the loop reaches it. An object deleted in the meantime is skipped. Any other
        error is raised and stops the loop.

        Args:
            service_name: Service name

        The two calls require the IAM action publicCloudProject:apiovh:ai/endpoint/get.
        """
        return self._each(
            lambda: self.list_project_ai_endpoints(
                service_name,
            ),
            lambda listed_id: self.get_project_ai_endpoint(service_name, listed_id),
        )

