    def all_project_ai_notebook_log_kinds(
        self, service_name: str, notebook_id: str
    ) -> t.Iterator[models.DbaasLogsLogKind]:
        """all_project_ai_notebook_log_kinds iterates over GET /v1/cloud/project/{serviceName}/ai/notebook/{notebookId}/log/kind (List log kinds).

        It lists the IDs with list_project_ai_notebook_log_kinds, then gets each object with get_project_ai_notebook_log_kind,
        only when the loop reaches it. An object deleted in the meantime is skipped. Any other
        error is raised and stops the loop.

        Args:
            service_name: Service name
            notebook_id: Notebook ID

        The two calls require the IAM action publicCloudProject:apiovh:ai/notebooklog/kind/get.
        """
        return self._each(
            lambda: self.list_project_ai_notebook_log_kinds(
                service_name,
                notebook_id,
            ),
            lambda listed_id: self.get_project_ai_notebook_log_kind(
                service_name, notebook_id, listed_id
            ),
        )

