    def all_project_credits(self, service_name: str) -> t.Iterator[models.CloudCredit]:
        """all_project_credits iterates over GET /v1/cloud/project/{serviceName}/credit (List project credits. Returns the IDs of the credits added to the project.).

        It lists the IDs with list_project_credits, then gets each object with get_project_credit,
        only when the loop reaches it. An object deleted in the meantime is skipped. Any other
        error is raised and stops the loop.

        Args:
            service_name: The project id

        The two calls require the IAM action publicCloudProject:apiovh:credit/get.
        """
        return self._each(
            lambda: self.list_project_credits(
                service_name,
            ),
            lambda listed_id: self.get_project_credit(service_name, listed_id),
        )

